async function load(){const chosen=$('planMonth').value;const d=await api('data'+(chosen?'&month='+encodeURIComponent(chosen):''));plan=d.plan;audit=d.audit;status.periods=d.periods;const selected=d.month;$('planMonth').innerHTML=opts(d.periods.map(p=>p.month));$('planMonth').value=selected;const [year,month]=selected.split('-').map(Number),last=new Date(Date.UTC(year,month,0)).getUTCDate(),from=selected+'-01',to=selected+'-'+String(last).padStart(2,'0');for(const id of ['from','to']){$(id).min=from;$(id).max=to}if($('from').value<from||$('from').value>to)$('from').value=from;if($('to').value<from||$('to').value>to)$('to').value=to;draft.clear();updatePlanningFilters();render();if(!plan.length)msg('No tenés campañas habilitadas en este momento.')}
const planFilters={jefe:new Set(),service:new Set()};
let planOptions={jefe:[],service:[]};
const campaignKey=r=>JSON.stringify([r.jefe,r.service]);
const clientOf=name=>(name.trim().split(/\s+/)[0]||'');
