 planOptions.service=[...pairs].map(([value,r])=>({value,label:campaignLabel(r.service,r.client)+(counts.get(campaignLabel(r.service,r.client))>1?' · '+display(r.jefe):'')})).sort((a,b)=>a.label.localeCompare(b.label,'es'));
