let sheet='';for(const group of campaignRows.values()){const first=group[0];sheet+=`<div class="campaign-block"><h3>${esc(campaignLabel(first.service,first.client))} <span>· ${esc(display(first.jefe))}</span></h3>`;let table='<table><thead><tr><th>Concepto</th>'+group.map(r=>`<th class="${['Sáb','Dom','Fer'].includes(r.kind)?'off':''}">${r.day.slice(-2)}<br>${esc(r.kind)}</th>`).join('')+'<th>Total mes</th></tr></thead><tbody>';for(const [field,label] of [['p','Personas requeridas'],['h','Horas por persona'],['hours','Horas objetivo']]){table+=`<tr><td>${label}</td>`+group.map(r=>{const v=effective(r);if(field==='hours')return `<td>${n(v.p*v.h)}</td>`;let changed=v[field]!=r[field+'0'];return `<td class="${changed?'changed':''} ${draft.has(r.id)?'dirty':''}"><input type="number" min="0" step="any" ${field==='h'?'max="24"':''} data-id="${r.id}" data-field="${field}" value="${Number(Number(v[field]).toFixed(2))}" aria-label="${label} ${r.day} ${esc(first.service)}">${changed?`<span class="old">Base: ${n(r[field+'0'])}</span>`:''}</td>`}).join('')+`<td>${field==='hours'?n(group.reduce((sum,r)=>{let v=effective(r);return sum+v.p*v.h},0)):'—'}</td></tr>`}sheet+=table+'</tbody></table></div>'}
$('sheet').innerHTML=sheet||'<p class="muted">No hay campañas para los filtros seleccionados.</p>';
$('sheet').querySelectorAll('input').forEach(el=>el.onchange=()=>{const r=plan.find(r=>r.id==el.dataset.id),v=effective(r),x=el.valueAsNumber;if(!Number.isFinite(x)||x<0||x>(el.dataset.field==='h'?24:100000)){msg('Valor inválido');render();return}mark(r,el.dataset.field==='p'?x:Number(v.p),el.dataset.field==='h'?x:Number(v.h));render()});
const groups=new Map();for(const r of all){const k=r.jefe+' / '+r.service,v=effective(r),g=groups.get(k)||[0,0,0];g[0]+=r.p0*r.h0;g[1]+=v.p*v.h;g[2]+=v.p!=r.p0||v.h!=r.h0?1:0;groups.set(k,g)}$('summary').innerHTML='<table><tr><th>Campaña</th><th>Base horas</th><th>Horas actuales</th><th>Desvío</th><th>Días modificados</th></tr>'+[...groups].map(([k,g])=>`<tr><td>${esc(k.includes(' / ')?display(k.slice(0,k.indexOf(' / ')))+k.slice(k.indexOf(' / ')):k)}</td><td>${n(g[0])}</td><td>${n(g[1])}</td><td>${signed(g[1]-g[0])}</td><td>${g[2]}</td></tr>`).join('')+'</table>';
