['historySearch','histFrom','histTo'].forEach(id=>$(id).addEventListener('input',render));$('reload').onclick=action(async()=>{if(!draft.size||confirm('¿Descartar cambios pendientes y actualizar?')){await load();if(status.role==='admin')await loadManagement()}});$('discard').onclick=()=>{if(confirm('¿Descartar cambios sin guardar?')){draft.clear();render()}};$('bulk').onclick=action(async()=>{const p=$('bp').value,h=$('bh').value,a=$('from').value,b=$('to').value;if(!a||!b||a>b||(!p&&!h))throw Error('Completá rango y al menos un valor');if((p!==''&&(!Number.isFinite(+p)||+p<0||+p>100000))||(h!==''&&(!Number.isFinite(+h)||+h<0||+h>24)))throw Error('Valores fuera de rango');const rows=selected().filter(r=>r.day>=a&&r.day<=b&&($('scope').value==='all'||r.p0>0));if(!rows.length)throw Error('No hay fechas para aplicar');if(!confirm(`Aplicar a ${rows.length} días de las campañas seleccionadas?`))return;for(const r of rows){let v=effective(r);mark(r,p===''?Number(v.p):+p,h===''?Number(v.h):+h)}render()});$('save').onclick=action(async()=>{if(!draft.size)return;const btn=$('save');btn.disabled=true;try{let r=await api('save',{changes:[...draft.values()]});await load();msg(`${r.count} días modificados y registrados.`)}finally{btn.disabled=!draft.size}});$('setpw').onclick=action(async()=>{await api('password',{name:$('account').value,password:$('newpw').value});$('newpw').value='';await loadManagement();msg('Acceso actualizado')});
