function csv(name,head,rows){const quote=x=>'"'+String(x??'').replace(/"/g,'""')+'"';const content='\ufeff'+[head,...rows].map(r=>r.map(quote).join(';')).join('\r\n');const u=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}const num=x=>String(x).replace('.',',');$('export').onclick=action(async()=>{if(draft.size)throw Error('Guardá o descartá los cambios pendientes antes de descargar el Excel');const response=await fetch('/?api=export_excel&month='+encodeURIComponent($('planMonth').value));if(!response.ok){const data=await response.json();throw Error(data.error||'No se pudo descargar el Excel')}const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='planificacion.xlsx';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);if(status.role==='admin'&&!plan.some(r=>String(r.client||'').trim().toLocaleLowerCase('es')==='personal'))msg('El mes seleccionado no tiene Personal cargado; el Excel incluye las campa?as guardadas para ese mes.')});
