async function loadManagement(){managementData=await api('management');const m=managementData;status.names=m.accounts.filter(a=>a.role==='jefe').map(a=>a.name);status.display_names=Object.fromEntries(m.accounts.map(a=>[a.name,a.display_name]));$('renameUser').innerHTML=opts(m.accounts.filter(a=>a.name!=='admin').map(a=>a.name));$('renameCampaign').innerHTML=m.campaigns.map((c,i)=>`<option value="${i}">${esc(display(c.jefe))} / ${esc(c.service)}</option>`).join('');const oldClientCampaign=$('clientCampaign').value;$('clientCampaign').innerHTML=$('renameCampaign').innerHTML;if([...$('clientCampaign').options].some(o=>o.value===oldClientCampaign))$('clientCampaign').value=oldClientCampaign;showCampaignClient();updatePeriods();for(const id of ['account','campaignOwner']){const old=$(id).value;$(id).innerHTML=opts(status.names);if(status.names.includes(old))$(id).value=old}$('campaignList').innerHTML='<table><tr><th>Campaña</th><th>Cliente</th><th>Jefe responsable</th></tr>'+m.campaigns.map(c=>`<tr><td>${esc(c.service)}</td><td>${esc(c.client)}</td><td>${esc(display(c.jefe))}</td></tr>`).join('')+'</table>';$('rolesTable').innerHTML='<table><tr><th>Usuario</th><th>Rol</th><th>Cuenta</th><th>Disponibilidad hoy</th></tr>'+m.accounts.map(a=>`<tr><td>${esc(a.display_name)}</td><td>${a.role==='admin'?'Administrador':'Jefe'}</td><td>${a.active?'Habilitada':'Sin activar'}</td><td>${m.absences.some(x=>!x.cancelled&&x.jefe===a.name&&x.start<=m.today&&x.end>=m.today)?'Ausente':'Disponible'}</td></tr>`).join('')+'</table>';renderAbsences();if(editingAbs===null)resetAbs();else {let a=m.absences.find(x=>x.id===editingAbs&&!x.cancelled);if(a)editAbs(a);else resetAbs()}}
function candidates(owner){return managementData.accounts.filter(a=>a.role==='jefe'&&a.active&&a.name!==owner&&!managementData.absences.some(x=>!x.cancelled&&x.jefe===a.name&&x.start<=$('absEnd').value&&x.end>=$('absStart').value)).map(a=>a.name)}
function coverageEditor(assignments={}){const owner=$('absOwner').value, subs=candidates(owner),list=managementData.campaigns.filter(x=>x.jefe===owner);$('allSub').innerHTML='<option value="">Sin cobertura</option>'+opts(subs);$('coverageEditor').innerHTML='<table><tr><th>Campaña titular</th><th>Jefe suplente</th></tr>'+list.map((x,i)=>`<tr><td>${esc(x.service)}</td><td><select data-service="${esc(x.service)}" aria-label="Suplente de ${esc(x.service)}"><option value="">Sin cobertura</option>${opts(subs)}</select></td></tr>`).join('')+'</table>';document.querySelectorAll('#coverageEditor select').forEach(el=>{if(subs.includes(assignments[el.dataset.service]))el.value=assignments[el.dataset.service]})}
