function editAbs(a){editingAbs=a.id;$('absOwner').innerHTML=opts(status.names);$('absOwner').value=a.jefe;$('absStart').value=a.start;$('absEnd').value=a.end;$('absReason').value=a.reason;$('absOwner').disabled=a.start<=managementData.today;$('absStart').disabled=a.start<=managementData.today;$('absSave').textContent='Actualizar ausencia y cobertura';coverageEditor(a.assignments)}
function renderAbsences(){const m=managementData;$('absenceList').innerHTML='<table><tr><th>Jefe</th><th>Desde</th><th>Hasta</th><th>Motivo</th><th>Estado</th><th>Campañas cubiertas</th><th>Acciones</th></tr>'+m.absences.map(a=>{const total=m.campaigns.filter(x=>x.jefe===a.jefe).length,covered=Object.keys(a.assignments).length,state=a.cancelled?'Cancelada':a.end<m.today?'Finalizada':a.start>m.today?'Programada':'Activa';return `<tr><td>${esc(display(a.jefe))}</td><td>${esc(a.start)}</td><td>${esc(a.end)}</td><td>${esc(a.reason)}</td><td>${state}</td><td>${covered}/${total}${covered<total?' · '+(total-covered)+' sin cobertura':''}<br>${Object.entries(a.assignments).map(([k,v])=>esc(k)+' → '+esc(display(v))).join('<br>')}</td><td>${!a.cancelled&&a.end>=m.today?`<button class="secondary" data-edit="${a.id}">Editar</button> <button class="secondary" data-cancel="${a.id}">Cancelar</button>`:'—'}</td></tr>`}).join('')+'</table>';$('absenceList').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editAbs(m.absences.find(a=>a.id===+b.dataset.edit)));$('absenceList').querySelectorAll('[data-cancel]').forEach(b=>b.onclick=action(async()=>{if(!confirm('¿Cancelar esta ausencia y devolver los accesos al titular?'))return;await api('absence_cancel',{id:+b.dataset.cancel});editingAbs=null;await loadManagement();msg('Ausencia cancelada')}));$('adminLog').innerHTML=m.events.length?m.events.map(e=>`<details><summary>${esc(new Date(e.stamp).toLocaleString('es-AR',{timeZone:'America/Argentina/Buenos_Aires'}))} · ${esc(e.actor)} · ${esc(e.event)}</summary><pre>${esc(JSON.stringify(JSON.parse(e.detail),null,2))}</pre></details>`).join(''):'Sin movimientos administrativos.'}
$('absNew').onclick=()=>resetAbs();$('absOwner').onchange=()=>coverageEditor();['absStart','absEnd'].forEach(id=>$(id).onchange=()=>coverageEditor(assignmentsNow()));$('fillSub').onclick=()=>document.querySelectorAll('#coverageEditor select').forEach(el=>el.value=$('allSub').value);$('absSave').onclick=action(async()=>{const assignments=assignmentsNow(),missing=Object.values(assignments).filter(x=>!x).length;if(missing&&!confirm(`${missing} campañas quedarán sin cobertura y solo serán accesibles por admin. ¿Continuar?`))return;await api('absence_save',{id:editingAbs,jefe:$('absOwner').value,start:$('absStart').value,end:$('absEnd').value,reason:$('absReason').value,assignments});editingAbs=null;await loadManagement();msg('Ausencia y permisos guardados')});
const workspacePages={planning:['Planificación','Consultá y actualizá la planificación de tu equipo.'],overview:['Resumen por campaña','Analizá los requeridos y las horas por responsable, cliente y campaña.'],siteReport:['Resumen site y Front','Revisá los resultados del mes y la variación por cliente.'],periods:['Meses de planificación','Administrá los períodos disponibles para los equipos.'],holidays:['Feriados','Consultá y gestioná las fechas de la programación.'],users:['Usuarios y roles','Administrá los accesos y responsables.'],campaigns:['Campañas','Organizá las campañas, clientes y responsables.'],personnel:['Personal','Importá y revisá los datos mensuales de Personal.'],vacations:['Vacaciones y cobertura','Planificá las ausencias y asigná coberturas.'],adminHistory:['Auditoría administrativa','Consultá el historial de acciones administrativas.']};
let workspacePage='planning';
function updateWorkspace(){
 const [title,description]=workspacePages[workspacePage]||workspacePages.planning;
 $('workspaceTitle').textContent=title;$('workspaceDescription').textContent=description;
 const field=workspacePage==='planning'?'planMonth':workspacePage==='overview'?'summaryMonth':workspacePage==='siteReport'?'siteMonth':null;
 const value=field?$(field).value:'';const badge=$('workspacePeriod');badge.hidden=!/^\d{4}-\d{2}$/.test(value);
 if(!badge.hidden){const [year,month]=value.split('-').map(Number);const label=new Intl.DateTimeFormat('es-AR',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(Date.UTC(year,month-1,1)));badge.textContent='Período consultado · '+label}
 document.querySelectorAll('[data-page]').forEach(item=>{if(item.dataset.page===workspacePage)item.setAttribute('aria-current','page');else item.removeAttribute('aria-current')});
}
['planMonth','summaryMonth','siteMonth'].forEach(id=>$(id).addEventListener('change',()=>queueMicrotask(updateWorkspace)));
function setMenuOpen(open){$('sidebar').hidden=!open;$('menuToggle').setAttribute('aria-expanded',String(open));$('menuToggle').setAttribute('aria-label',open?'Ocultar menú':'Mostrar menú');$('menuBackdrop').hidden=!(open&&window.matchMedia('(max-width: 700px)').matches)}
