let summaryData={rows:[]};
const summaryFilters={jefe:new Set(),client:new Set(),campaign:new Set()};
let summaryOptions={jefe:[],client:[],campaign:[]};
const summaryCampaignLabel=name=>{const clients=[...new Set(summaryData.rows.filter(r=>r.campaign===name).map(r=>r.client))];return clients.length===1?campaignLabel(name,clients[0]):name};
const summaryFields=[['summaryChief','jefe',display],['summaryClient','client',x=>x||'Sin asignar'],['summaryCampaign','campaign',summaryCampaignLabel]];
function renderSummary(){
 const all=summaryData.rows;
 for(const [,field] of summaryFields){const valid=new Set(all.map(r=>r[field]));summaryFilters[field]=new Set([...summaryFilters[field]].filter(v=>valid.has(v)))}
 for(const [id,field,label] of summaryFields){
   const values=[...new Set(all.filter(row=>summaryFilters[field].has(row[field])||summaryFields.every(([,other])=>other===field||matches(summaryFilters[other],row[other]))).map(row=>row[field]))];
   summaryOptions[field]=values.map(value=>({value,label:label(value)})).sort((a,b)=>a.label.localeCompare(b.label,'es'));
   setFilterLabel(id,summaryOptions[field],summaryFilters[field],field==='campaign'?'Todas':'Todos');
 }
 const rows=all.filter(row=>summaryFields.every(([,field])=>matches(summaryFilters[field],row[field])));
 $('summaryDay').textContent='Requerido: primer día hábil ('+(summaryData.first_business_day||'sin fecha disponible')+'), excluyendo fines de semana, feriados oficiales disponibles y fechas adicionales marcadas. Horas: suma del mes.';
 $('summaryCount').textContent=rows.length+' '+(rows.length===1?'campaña':'campañas');
 const requiredValues=rows.filter(r=>r.required!==null && r.required!==undefined);
 const requiredTotal=requiredValues.reduce((sum,r)=>sum+Number(r.required),0);
 const hoursTotal=rows.reduce((sum,r)=>sum+Number(r.hours||0),0);
 $('summaryTotals').innerHTML=`<div class="metric">Total requerido<b>${requiredValues.length?n(requiredTotal):'—'}</b></div><div class="metric">Total horas<b>${n(hoursTotal)}</b></div>`;
 $('summaryExport').disabled=!rows.length;
 $('summaryTable').innerHTML=rows.length?'<table><thead><tr><th>Jefe</th><th>Cliente</th><th>Campaña</th><th>Requerido</th><th>Horas</th></tr></thead><tbody>'+rows.map(r=>`<tr><td data-label="Jefe">${esc(display(r.jefe))}</td><td data-label="Cliente">${esc(r.client||'Sin asignar')}</td><td data-label="Campaña">${esc(r.campaign)}</td><td data-label="Requerido">${r.required===null?'—':n(r.required)}</td><td data-label="Horas">${n(r.hours)}</td></tr>`).join('')+'</tbody></table>':'<p class="muted">No hay campañas para los filtros seleccionados.</p>';
}
async function loadSummary(){const el=$('summaryMonth'),old=el.value,months=status.periods.map(p=>p.month);el.innerHTML=opts(months);el.value=months.includes(old)?old:$('planMonth').value;summaryData=await api('admin_summary&month='+encodeURIComponent(el.value));renderSummary()}
$('summaryMonth').onchange=action(loadSummary);

$('summaryReload').onclick=action(loadSummary);
$('summaryClear').onclick=()=>{for(const set of Object.values(summaryFilters))set.clear();renderSummary()};
$('summaryExport').onclick=action(async()=>{if(draft.size&&!confirm('Hay cambios de planificación sin guardar. El resumen incluye únicamente los datos guardados. ¿Descargar de todos modos?'))return;const params=new URLSearchParams({api:'export_summary',month:$('summaryMonth').value});for(const [field,param] of [['jefe','chief'],['client','client'],['campaign','campaign']])for(const value of summaryFilters[field])params.append(param,value);const response=await fetch('/?'+params);if(!response.ok){const data=await response.json();throw Error(data.error||'No se pudo descargar el resumen')}const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='resumen_campanas.xlsx';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});


async function loadHolidays(){
 const year=$('holidayYear').value||$('planMonth').value.slice(0,4);
 if(!/^\d{4}$/.test(year)||+year<1900)throw Error('Indicá un año válido');
 $('holidayYear').value=year;
 const data=await api('holidays&year='+encodeURIComponent(year)),marked=new Map(data.marked.map(r=>[r.day,r]));
 $('holidayInfo').textContent=year==='2026'?'Feriados nacionales de 2026. Los días no laborables turísticos y locales no se marcan automáticamente.':year==='2027'?'Lista parcial: feriados nacionales inamovibles. Revisá los trasladables y los días adicionales en el calendario oficial.':'No hay un listado nacional verificado incorporado para este año. Consultá la fuente oficial y agregá las fechas que correspondan.';
 $('officialHolidays').innerHTML=data.official.length?'<table><thead><tr><th>Fecha</th><th>Feriado nacional</th><th>Estado</th><th>Acción</th></tr></thead><tbody>'+data.official.map(r=>{const saved=marked.get(r.day),state=saved?'Marcado':'Sin marcar',label=saved?.source==='existing'?'Identificar':saved?'Marcado':'Marcar';return `<tr><td>${esc(r.day)}</td><td>${esc(r.name)}</td><td>${state}</td><td><button class="secondary" data-official="${esc(r.day)}" ${saved&&saved.source!=='existing'?'disabled':''}>${label}</button></td></tr>`}).join('')+'</tbody></table>':'<p class="muted">Sin fechas sugeridas para este año.</p>';
 $('officialHolidays').querySelectorAll('[data-official]').forEach(b=>b.onclick=action(async()=>{if(draft.size)throw Error('Guardá o descartá los cambios pendientes antes de modificar feriados');const r=await api('holiday_mark',{day:b.dataset.official,source:'official'});await load();await loadHolidays();msg('Feriado marcado. Registros actualizados: '+r.records)}));
 $('markedHolidays').innerHTML=data.marked.length?'<table><thead><tr><th>Fecha</th><th>Motivo</th><th>Tipo</th><th>Acción</th></tr></thead><tbody>'+data.marked.map(r=>`<tr><td>${esc(r.day)}</td><td>${esc(r.name)}</td><td>${r.source==='official'?'Nacional':r.source==='custom'?'Adicional':'Existente'}</td><td><button class="secondary" data-remove-holiday="${esc(r.day)}">Quitar</button></td></tr>`).join('')+'</tbody></table>':'<p class="muted">No hay feriados marcados para este año.</p>';
 $('markedHolidays').querySelectorAll('[data-remove-holiday]').forEach(b=>b.onclick=action(async()=>{if(draft.size)throw Error('Guardá o descartá los cambios pendientes antes de modificar feriados');if(!confirm('¿Quitar el feriado del '+b.dataset.removeHoliday+' de toda la programación?'))return;const r=await api('holiday_remove',{day:b.dataset.removeHoliday});await load();await loadHolidays();msg('Feriado quitado. Registros actualizados: '+r.records)}));
}
$('holidayLoad').onclick=action(loadHolidays);
$('holidayYear').onchange=action(loadHolidays);
$('holidayAdd').onclick=action(async()=>{if(draft.size)throw Error('Guardá o descartá los cambios pendientes antes de modificar feriados');const day=$('holidayDate').value,name=$('holidayName').value.trim();if(!day||!name)throw Error('Completá la fecha y el motivo');const r=await api('holiday_mark',{day,name,source:'custom'});$('holidayYear').value=day.slice(0,4);$('holidayDate').value='';$('holidayName').value='';await load();await loadHolidays();msg('Fecha marcada. Registros actualizados: '+r.records)});


function setFilterLabel(id,options,selection,emptyLabel){
 const selected=options.filter(o=>selection.has(o.value));
 $(id).textContent=!selection.size?emptyLabel:selected.length===1?selected[0].label:selection.size+' seleccionados';
 $(id).setAttribute('aria-label',id==='jefe'?'Filtrar por jefe de site':id==='service'?'Filtrar por cliente y campaña':'Filtrar por '+({summaryChief:'jefe',summaryClient:'cliente',summaryCampaign:'campaña',siteOwnerFilter:'responsable',siteCampaignFilter:'cliente o campaña del resumen',frontCampaignFilter:'cliente o campaña del Front'}[id]||'opciones'));
}
let filterSession=null;
function openFilter(title,options,selected,onApply){
 const dialog=$('filterDialog'),search=$('filterSearch');
 filterSession={options,chosen:new Set(selected),onApply};$('filterTitle').textContent='Filtrar por '+title;search.value='';drawFilter();dialog.showModal();search.focus();
}
function drawFilter(){
 const term=$('filterSearch').value.trim().toLocaleLowerCase('es');
 const visible=filterSession.options.map((item,index)=>({...item,index})).filter(item=>item.label.toLocaleLowerCase('es').includes(term));
 $('filterOptions').innerHTML=visible.length?visible.map(item=>`<label class="filter-option"><input type="checkbox" data-index="${item.index}" ${filterSession.chosen.has(item.value)?'checked':''}><span>${esc(item.label)}</span></label>`).join(''):'<p class="muted">No hay opciones que coincidan con la búsqueda.</p>';
 $('filterOptions').querySelectorAll('input').forEach(el=>el.onchange=()=>{const item=filterSession.options[Number(el.dataset.index)];if(el.checked)filterSession.chosen.add(item.value);else filterSession.chosen.delete(item.value);$('filterCount').textContent=filterSession.chosen.size?(filterSession.chosen.size+' opciones seleccionadas'):'0 opciones seleccionadas · se muestran todas'});
 $('filterCount').textContent=filterSession.chosen.size?(filterSession.chosen.size+' opciones seleccionadas'):'0 opciones seleccionadas · se muestran todas';
}
$('filterSearch').oninput=drawFilter;
$('filterAll').onclick=()=>{const term=$('filterSearch').value.trim().toLocaleLowerCase('es');for(const item of filterSession.options)if(item.label.toLocaleLowerCase('es').includes(term))filterSession.chosen.add(item.value);drawFilter()};
$('filterNone').onclick=()=>{filterSession.chosen.clear();drawFilter()};
$('filterCancel').onclick=$('filterClose').onclick=()=>$('filterDialog').close();
$('filterApply').onclick=()=>{const selected=new Set(filterSession.chosen),apply=filterSession.onApply;$('filterDialog').close();apply(selected)};
$('jefe').onclick=()=>openFilter('jefe de site',planOptions.jefe,planFilters.jefe,values=>{planFilters.jefe=values;updatePlanningFilters();render()});
$('service').onclick=()=>openFilter('cliente y campaña',planOptions.service,planFilters.service,values=>{planFilters.service=values;updatePlanningFilters();render()});
for(const [id,field] of summaryFields)$(id).onclick=()=>openFilter(field==='jefe'?'jefe':field==='client'?'cliente':'campaña',summaryOptions[field],summaryFilters[field],values=>{summaryFilters[field]=values;renderSummary()});


