let personalPreviewPayload=null,personalDraftId=null,personalDraftData=null;
function clearPersonalPreview(){personalPreviewPayload=null;personalDraftId=null;personalDraftData=null;$('personalSave').disabled=true;$('personalApply').disabled=true;$('personalResult').innerHTML=''}
['personalMonth','personalFile','personalSheet','personalText'].forEach(id=>$(id).addEventListener(id==='personalText'?'input':'change',clearPersonalPreview));
async function personalInput(){
 const month=$('personalMonth').value;if(!month)throw Error('Seleccioná el mes de la tabla');
 const file=$('personalFile').files[0],sheet=$('personalSheet').value.trim();
 if(!file)return {month,text:$('personalText').value};
 if(file.size>1400000)throw Error('El archivo supera el tamaño permitido');
 if(file.name.toLowerCase().endsWith('.xlsx')){const encoded=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(Error('No se pudo leer el archivo'));r.readAsDataURL(file)});return {month,file_base64:encoded,sheet}}
 return {month,text:await file.text()};
}
function renderPersonalPreview(data,saved=false){
 const missingOwners=data.rows.filter(r=>!r.missing_data&&!r.suggested_responsibles.length),missingData=data.rows.filter(r=>r.missing_data),diff=data.total_differences||[],blocks=data.block_differences||[],plp=data.format==='plp';
 let warnings=diff.length?`<details open><summary>Hay ${diff.length} diferencias entre los totales informados y la suma de las campañas.</summary><div class="scroll"><table><thead><tr><th>Total</th><th>Fecha</th><th>Informado</th><th>Suma de campañas</th></tr></thead><tbody>${diff.map(d=>`<tr><td>${esc(d.total)}</td><td>${esc(d.day)}</td><td>${n(d.reported)}</td><td>${n(d.calculated)}</td></tr>`).join('')}</tbody></table></div></details>`:plp?'<p class="muted">Las horas y dotaciones coinciden en las fechas con datos.</p>':(data.total_checks?'<p class="muted">No se detectaron diferencias en los totales informados.</p>':'<p class="muted">No hay totales informados para contrastar.</p>');
 if(blocks.length)warnings+=`<details open><summary>Hay ${blocks.length} diferencias entre horas y dotación; corregí el archivo antes de incorporarlo.</summary><div class="scroll"><table><thead><tr><th>Campaña</th><th>Fecha</th><th>Personas</th><th>Horas</th></tr></thead><tbody>${blocks.map(d=>`<tr><td>${esc(d.campaign)}</td><td>${esc(d.day)}</td><td>${n(d.people)}</td><td>${n(d.hours)}</td></tr>`).join('')}</tbody></table></div></details>`;
 if(missingData.length)warnings+=`<p class="warning">${missingData.length} campañas sin datos completos no se incorporarán: ${missingData.map(r=>esc(r.campaign)).join(', ')}. Las celdas vacías no se interpretan como cero.</p>`;
 const suggestedOwners=[...new Set(data.rows.flatMap(r=>r.suggested_responsibles))];
 const rows=data.rows.map((r,i)=>{const suggested=r.suggested_responsibles[0],existing=suggested&&status.names.find(name=>display(name).toLocaleUpperCase('es')===suggested.toLocaleUpperCase('es'));const selected=existing?'e:'+existing:suggested?'n:'+suggested:'';const existingOptions=status.names.map(name=>`<option value="e:${esc(name)}" ${selected==='e:'+name?'selected':''}>${esc(display(name))}</option>`).join('');const newOptions=suggestedOwners.filter(owner=>!status.names.some(name=>display(name).toLocaleUpperCase('es')===owner.toLocaleUpperCase('es'))).map(owner=>`<option value="n:${esc(owner)}" ${selected==='n:'+owner?'selected':''}>Crear acceso: ${esc(owner)}</option>`).join('');const extra=plp?`<td>${esc(r.source_subcampaign||'—')}</td><td>${esc([r.source_province,r.source_site].filter(Boolean).join(' / ')||'—')}</td><td>${esc(r.source_origin||'—')}</td><td>${esc(r.source_status||'—')}</td>`:'';return `<tr><td>${esc(r.reference_campaign||r.campaign)}</td>${extra}<td><select data-personal-owner="${i}" aria-label="Responsable de ${esc(r.campaign)}" ${r.missing_data?'disabled':''}><option value="">Elegir responsable</option>${newOptions}${existingOptions}</select></td><td>${r.days[0].hours==null?'—':n(r.days[0].hours)}</td><td>${r.people_first_day==null?'—':n(r.people_first_day)}</td><td>${r.missing_data?'Sin datos completos':n(r.total_hours)}</td></tr>`}).join('');
 const extraHeaders=plp?'<th>Subcampaña</th><th>Provincia / Site</th><th>Origen PLP</th><th>Control</th>':'';
 $('personalResult').innerHTML=`<hr><h3>${saved?'Previa guardada':'Resultado de la vista previa'} · ${esc(data.month)}</h3><p>${plp?'Archivo PLP · ':''}${data.campaigns} campañas · ${data.days} días · ${missingOwners.length} campañas sin responsable sugerido.</p>${warnings}<p class="muted">La vista muestra el primer día y las horas del mes. Revisá los responsables. Si elegís «Crear acceso», el usuario y la clave inicial serán el nombre indicado; al ingresar deberá cambiarla. Las campañas sin datos completos se conservan en la previa y no se incorporan.</p><div class="scroll"><table><thead><tr><th>Campaña</th>${extraHeaders}<th>Responsable</th><th>Horas primer día</th><th>Personas primer día</th><th>Horas del mes</th></tr></thead><tbody>${rows}</tbody></table></div>`;
}
$('personalPreview').onclick=action(async()=>{clearPersonalPreview();const payload=await personalInput();const result=await api('personal_preview',payload);personalPreviewPayload=payload;personalDraftData=result;renderPersonalPreview(result);$('personalSave').disabled=false;msg('Vista previa preparada')});
$('personalSave').onclick=action(async()=>{if(!personalPreviewPayload)throw Error('Primero previsualizá la tabla');const result=await api('personal_save',personalPreviewPayload);$('personalSave').disabled=true;personalDraftId=result.id;$('personalApply').disabled=Boolean(personalDraftData.block_differences?.length);msg('Previa guardada para '+result.month+'. Todavía no se aplicó a la planificación.')});
$('personalLoad').onclick=action(async()=>{clearPersonalPreview();const month=$('personalMonth').value;if(!month)throw Error('Seleccioná el mes');const result=await api('personal_draft&month='+encodeURIComponent(month));if(!result.draft){$('personalResult').innerHTML='';msg('No hay una previa guardada para ese mes');return}personalDraftId=result.draft.id;personalDraftData=result.draft.data;renderPersonalPreview(personalDraftData,true);$('personalApply').disabled=Boolean(personalDraftData.block_differences?.length);msg('Previa guardada cargada')});


$('personalApply').onclick=action(async()=>{
 if(draft.size)throw Error('Guardá o descartá los cambios pendientes de la planificación antes de incorporar Personal');
 if(!personalDraftId||!personalDraftData)throw Error('Guardá o cargá primero una previa');
 const inputs=[...$('personalResult').querySelectorAll('[data-personal-owner]')];
 if(inputs.length!==personalDraftData.rows.length)throw Error('No se pudieron leer las asignaciones');
 const assignments=inputs.map((input,i)=>{if(personalDraftData.rows[i].missing_data)return {name:'',create:false};if(!input.value)throw Error('Falta asignar responsable a '+personalDraftData.rows[i].campaign);return {name:input.value.slice(2),create:input.value.startsWith('n:')}});
 const pending=personalDraftData.rows.filter(row=>row.missing_data);
 if(!confirm('Se incorporarán las campañas al mes '+personalDraftData.month+'. Los valores existentes de esas campañas y fechas serán reemplazados, incluidos los ceros; los demás meses no cambian.'+(pending.length?' No se incorporarán las campañas sin datos completos: '+pending.map(row=>row.campaign).join(', ')+'.':'')+' ¿Continuar?'))return;
 const result=await api('personal_publish',{id:personalDraftId,assignments});status=await api('status');await load();await loadManagement();$('personalApply').disabled=true;msg('Personal incorporado: '+result.campaigns+' campañas, '+result.inserted+' días nuevos y '+result.updated+' actualizados.'+(result.pending_campaigns?.length?' Pendientes sin datos: '+result.pending_campaigns.join(', ')+'.':''));
});

init().then(()=>{if(status?.actor&&!status.must_change)updateWorkspace()}).catch(e=>msg(e.message));

let siteData=null;
const siteFilters={owner:new Set(),campaign:new Set(),front:new Set()};
let siteOptions={owner:[],campaign:[],front:[]};
async function loadSiteReport(){
 const select=$('siteMonth'), selected=select.value||$('planMonth').value;
 const data=await api('site_report&month='+encodeURIComponent(selected));siteData=data;
 select.innerHTML=opts(data.months);select.value=data.month;
 renderSiteReport();
}
function renderSiteReport(){
 const data=siteData;if(!data)return;
 const c=data.current,p=data.previous,delta=p&&c.total_required!=null&&p.total_required!=null?c.total_required-p.total_required:null;
 for(const field of ['owner','campaign']){
  const valid=new Set(c.rows.map(r=>r[field]));siteFilters[field]=new Set([...siteFilters[field]].filter(v=>valid.has(v)));
 }
 const validFront=new Set(data.changes.map(r=>r.campaign));siteFilters.front=new Set([...siteFilters.front].filter(v=>validFront.has(v)));
 for(const field of ['owner','campaign']){
  const other=field==='owner'?'campaign':'owner';
  const values=[...new Set(c.rows.filter(r=>siteFilters[field].has(r[field])||matches(siteFilters[other],r[other])).map(r=>r[field]))];
  siteOptions[field]=values.map(value=>({value,label:value})).sort((a,b)=>a.label.localeCompare(b.label,'es'));
 }
 siteOptions.front=[...validFront].map(value=>({value,label:value})).sort((a,b)=>a.label.localeCompare(b.label,'es'));
 for(const [id,field] of [['siteOwnerFilter','owner'],['siteCampaignFilter','campaign'],['frontCampaignFilter','front']])setFilterLabel(id,siteOptions[field],siteFilters[field],'Todos');
 const rows=c.rows.filter(r=>matches(siteFilters.owner,r.owner)&&matches(siteFilters.campaign,r.campaign));
 const filtered=siteFilters.owner.size||siteFilters.campaign.size;
 const total=field=>{const values=rows.map(r=>r[field]).filter(v=>v!==null&&v!==undefined);return values.length?values.reduce((sum,v)=>sum+Number(v),0):null};
 const totalRequired=filtered?total('required'):c.total_required,totalHours=filtered?total('hours'):c.total_hours;
 $('siteSource').textContent=c.source+(c.historical?' · Valores originales del archivo; un espacio vacío indica que no había dato.':' · Requerido del primer día hábil; horas de todos los días.');
 $('siteMetrics').innerHTML=[['Requerido total compañía',c.total_required],['Horas objetivo compañía',c.total_hours],['Variación mensual compañía',delta]].map(([label,value])=>`<div class="metric">${label}<b>${value==null?'—':n(value)}</b></div>`).join('');
 const val=x=>x==null?'—':n(x);
 $('siteTable').innerHTML=rows.length?'<table><thead><tr><th>Responsable</th><th>Cliente / campaña</th><th>Requerido</th><th>Horas objetivo</th></tr></thead><tbody>'+rows.map(r=>`<tr><td>${esc(r.owner)}</td><td>${esc(r.campaign)}</td><td>${val(r.required)}</td><td>${val(r.hours)}</td></tr>`).join('')+`<tr><th colspan="2">${filtered?'Total filtrado':'Total compañía'}</th><th>${val(totalRequired)}</th><th>${val(totalHours)}</th></tr></tbody></table>`:'<p class="muted">No hay resultados para los filtros seleccionados.</p>';
 $('frontInfo').textContent=p?'Comparación por cliente con '+data.previous_month+'. Personal se calcula con las horas del mes divididas por 6 y por los días hábiles; el histórico conserva los valores del Excel.':'No hay datos del mes anterior para comparar.';
 const changes=data.changes.filter(r=>matches(siteFilters.front,r.campaign));
 const changeTable=(title,items)=>items.length?`<h4>${title}</h4><table><thead><tr><th>Cliente</th><th>Requerido actual</th><th>Mes anterior</th><th>Variación</th></tr></thead><tbody>${items.map(r=>`<tr><td>${esc(r.campaign)}</td><td>${val(r.required)}</td><td>${val(r.previous)}</td><td>${signed(r.delta)}</td></tr>`).join('')}<tr><th colspan="3">Total</th><th>${signed(items.reduce((sum,r)=>sum+r.delta,0))}</th></tr></tbody></table>`:'';
 $('frontTable').innerHTML=changes.length?changeTable('Clientes que reducen requeridos',changes.filter(r=>r.delta<0))+changeTable('Clientes que incrementan requeridos',changes.filter(r=>r.delta>0)):'<p class="muted">'+(p?'No hay variaciones para el filtro seleccionado.':'Sin comparación disponible.')+'</p>';
}
$('siteMonth').onchange=action(loadSiteReport);$('siteReload').onclick=action(loadSiteReport);
for(const [id,field,title] of [['siteOwnerFilter','owner','responsable'],['siteCampaignFilter','campaign','cliente / campaña'],['frontCampaignFilter','front','cliente']])$(id).onclick=()=>openFilter(title,siteOptions[field],siteFilters[field],values=>{siteFilters[field]=values;renderSiteReport()});
$('siteClear').onclick=()=>{siteFilters.owner.clear();siteFilters.campaign.clear();renderSiteReport()};
$('frontClear').onclick=()=>{siteFilters.front.clear();renderSiteReport()};
$('siteExport').onclick=action(async()=>{const params=new URLSearchParams({api:'export_site_report',month:$('siteMonth').value});for(const [field,param] of [['owner','owner'],['campaign','campaign'],['front','front_campaign']])for(const value of siteFilters[field])params.append(param,value);const response=await fetch('/?'+params);if(!response.ok){const data=await response.json();throw Error(data.error||'No se pudo descargar el Excel')}const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='resumen_site_front.xlsx';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
